// Campaign missions in replays and saves (docs/contracts.md, sections 7 and 9).
//
// A mission game starts from a mission file of the game (apps/game/missions,
// generated by tools/gen_missions.py) and its start options: the seed, the
// game speed and the mission's lobby options (difficulty). Replays and saves
// name the file by id and SHA-256 instead of carrying it; the loader fetches
// it and refuses a file whose hash differs (the mission changed).

import { FACTORY_LOSS_RULES, GAME_SPEEDS, MOVEMENT_MODELS, SEED_MAX, SHA256_RE } from './constants.js';
import { fail, int, isPlainObject, matches, object, oneOf } from './check.js';
import { COOP_MISSIONS } from './coop-missions.js';

export { COOP_MISSIONS };

/** The co-op mission with `id`, or null. */
export function coopMission(id) {
  return COOP_MISSIONS.find((m) => m.id === id) ?? null;
}

/**
 * A co-op mission played online (lobby, start, online replays and saves):
 * `{ id, hash, options }`, one of COOP_MISSIONS with its file's hash and a
 * value for every one of its options. Returns a fresh object; throws
 * ProtocolError otherwise.
 */
export function validCoopMission(v, what = 'mission') {
  object(v, ['id', 'hash', 'options'], what);
  const id = matches(v.id, MISSION_ID_RE, `${what}.id`);
  const m = coopMission(id);
  if (!m) fail(`${what}: ${id} is not a co-op mission`);
  if (matches(v.hash, SHA256_RE, `${what}.hash`) !== m.hash) fail(`${what}: the mission file is not this version's`);
  if (!isPlainObject(v.options)) fail(`${what}.options must be an object`);
  const options = {};
  for (const k of Object.keys(v.options)) if (!Object.hasOwn(m.options, k)) fail(`${what}.options: unknown option ${k}`);
  for (const [k, o] of Object.entries(m.options)) {
    options[k] = Object.hasOwn(v.options, k) ? oneOf(v.options[k], o.values, `${what}.options.${k}`) : o.default;
  }
  return { id, hash: m.hash, options };
}

/** Mission ids: the file names of apps/game/missions. */
export const MISSION_ID_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;
/** Mission lobby option keys and values (OpenRA ScriptLobbyDropdown ids and values). */
export const MISSION_OPTION_RE = /^[a-z0-9][a-z0-9_-]{0,31}$/i;
export const MISSION_OPTIONS_MAX = 8;
export const MISSION_OPTION_KEYS = ['seed', 'gameSpeed', 'options', 'movement', 'factoryLoss'];

/**
 * `{ seed, gameSpeed, options: { key: value }, movement?, factoryLoss? }`,
 * validated; returns a fresh object. `movement` (MOVEMENT_MODELS) and
 * `factoryLoss` (FACTORY_LOSS_RULES) are left out by mission saves and
 * replays from before them: they play with `webra`.
 */
export function validateMissionOptions(v, what = 'options') {
  object(v, MISSION_OPTION_KEYS, what);
  const opts = v.options;
  if (!isPlainObject(opts)) fail(`${what}.options must be an object`);
  const keys = Object.keys(opts);
  if (keys.length > MISSION_OPTIONS_MAX) fail(`${what}.options has too many entries`);
  const options = {};
  for (const k of keys.sort()) {
    matches(k, MISSION_OPTION_RE, `${what}.options key`);
    options[k] = matches(opts[k], MISSION_OPTION_RE, `${what}.options.${k}`);
  }
  const out = {
    seed: int(v.seed, 0, SEED_MAX, `${what}.seed`),
    gameSpeed: oneOf(v.gameSpeed, GAME_SPEEDS, `${what}.gameSpeed`),
    options,
  };
  if (v.movement !== undefined) out.movement = oneOf(v.movement, MOVEMENT_MODELS, `${what}.movement`);
  if (v.factoryLoss !== undefined) out.factoryLoss = oneOf(v.factoryLoss, FACTORY_LOSS_RULES, `${what}.factoryLoss`);
  return out;
}

/** `{ id, hash }` of a mission file, validated; returns a fresh object. */
export function validMissionRef(v, what = 'mission') {
  object(v, ['id', 'hash'], what);
  return { id: matches(v.id, MISSION_ID_RE, `${what}.id`), hash: matches(v.hash, SHA256_RE, `${what}.hash`) };
}
